-- Run once in a new Supabase project's SQL Editor. Never put service_role in client code.
create table if not exists public.codes (
  id uuid primary key default gen_random_uuid(),
  code text collate "C" not null unique check (code ~ '^NG-[A-Za-z0-9]{8}$'),
  status text not null default 'pending' check (status in ('pending','approved','rejected')),
  created_at timestamptz not null default now(),
  reviewed_at timestamptz
);
create index if not exists codes_status_created on public.codes(status,created_at);
create table if not exists public.reports (
  id uuid primary key default gen_random_uuid(),
  code text collate "C" not null check (code ~ '^NG-[A-Za-z0-9]{8}$'),
  reason text not null check (reason = 'not_working'),
  reporter_hash text not null check (reporter_hash ~ '^[a-f0-9]{64}$'),
  created_at timestamptz not null default now(),
  resolved boolean not null default false,
  unique(code,reporter_hash)
);
create index if not exists reports_unresolved on public.reports(resolved,created_at);
create table if not exists public.request_limits (
  key text primary key,
  window_start timestamptz not null,
  count integer not null check (count > 0)
);
alter table public.codes enable row level security;
alter table public.reports enable row level security;
alter table public.request_limits enable row level security;
-- No direct anonymous/authenticated writes. The server authenticates admin and uses service_role.
revoke all on public.codes, public.reports, public.request_limits from anon, authenticated;
grant all on public.codes, public.reports, public.request_limits to service_role;
create or replace function public.consume_rate_limit(p_key text,p_limit integer)
returns boolean language plpgsql security definer set search_path = public, pg_temp as $$
declare current_window timestamptz := date_trunc('minute',now()); accepted integer;
begin
  if p_limit < 1 or p_limit > 100 or length(p_key) > 100 then return false; end if;
  on conflict(key) do update set
    count = case when bucket.window_start < current_window then 1 else bucket.count + 1 end,
    window_start = current_window
  where bucket.window_start < current_window or bucket.count < p_limit
  returning count into accepted;
  -- Keep hash buckets short-lived; this bound also prevents indefinite growth across source addresses.
  delete from public.request_limits where window_start < now() - interval '1 day';
  return accepted is not null;
end;
$$;
revoke all on function public.consume_rate_limit(text,integer) from public,anon,authenticated;
grant execute on function public.consume_rate_limit(text,integer) to service_role;
-- Before opening public submissions, configure auth/site URL, disable public signup,
-- add a confirmed admin user, and set ADMIN_EMAILS server-side.

-- CURRENT DYNAMIC ADMIN UPGRADE
-- Upgrade an existing project. Rerunnable; existing code statuses/content are retained.
-- No anonymous access is granted. New codes publish automatically by default.
begin;
alter table public.codes drop constraint if exists codes_status_check;
alter table public.codes add constraint codes_status_check check(status in ('pending','approved','rejected','deleted'));
alter table public.codes add column if not exists deleted_at timestamptz;
create sequence if not exists public.codes_sort_order_seq;
alter table public.codes add column if not exists sort_order bigint;
update public.codes set sort_order=nextval('public.codes_sort_order_seq') where sort_order is null;
alter table public.codes alter column sort_order set default nextval('public.codes_sort_order_seq');
alter table public.codes alter column sort_order set not null;
grant usage,select on sequence public.codes_sort_order_seq to service_role;
create table if not exists public.site_settings(
 id smallint primary key default 1 check(id=1),
 auto_approve boolean not null default true,
 submissions_enabled boolean not null default true,
 content jsonb not null,
 revision bigint not null default 1,
 codes_revision bigint not null default 1,
 updated_at timestamptz not null default now()
);
alter table public.site_settings enable row level security;
revoke all on public.site_settings from anon,authenticated;
grant all on public.site_settings to service_role;
values(1,true,true,'{"siteName":"مساعد أكواد نسك","description":"أداة مستقلة مجانية لتسهيل نسخ أكواد تحدي نسك ومتابعتها، مع دليل وروابط رسمية ومعلومات موثقة عن المسابقة.","developerName":"أحمد عيد","prayerTitle":"لو الأداة نفعتك، افتكرنا بدعوة طيبة.","prayerBody":"ادعُ لي ولوالديّ بظهر الغيب. ربنا يكتب لنا ولكم زيارة بيته الحرام.","home":{"eyebrow":"أكوادك ودليلك، في مكان واحد","title":"كودك التالي،","highlight":"بخطوة أسهل.","description":"انسخ كودًا، استخدمه داخل نسك، وارجع كمّل من مكانك. هنساعدك تتابع من غير ما تتوه بين الأكواد."},"links":{"platform":"https://www.nusuk.sa/","app":"https://services.nusuk.sa/app?p=27","ios":"https://apps.apple.com/sa/app/nusuk-%D9%86%D8%B3%D9%83/id6469515422","android":"https://play.google.com/store/apps/details?id=com.moh.nusukapp","download":"https://onelink.to/nusuk","announcement":"https://www.facebook.com/MyNusuk/posts/pfbid034WZFCPLLjXcw8kTx1d8AwrZbCSX9q2dKZBr8MV9RVXvaBT6t1YC1uKdEHfYztcfHl","support":"https://www.nusuk.sa/contact-us","faq":"https://www.nusuk.sa/faq","umrah":"https://www.nusuk.sa/umrah","linkedin":"https://www.linkedin.com/in/eiido","github":"https://github.com/eiido"},"verifiedAt":"2026-11-04T14:32:15Z","campaign":{"start":"2026-11-01","startStatus":"reported","startSource":"https://nabdapp.com/t/180223066-916a4c","end":null,"dailyLimitStatus":"unverified","verificationNote":"الإعلان الرسمي يؤكد الجوائز والمشاركة العالمية، ولا يوضح الحد اليومي للأسئلة أو الفرص ولا تاريخ نهاية المسابقة.","intro":"المشاركة متاحة من جميع أنحاء العالم وفق إعلان نسك. شروط التحدي داخل التطبيق هي المرجع للأهلية والفرص.","umrahTitle":"فائز يوميًا،\nوعمرة لشخصين.","umrahDescription":"للفائز ومرافق يختاره، وتشمل التأشيرة وتذاكر الطيران وإقامة ١٠ ليالٍ في مكة والمدينة.","zamzamTitle":"١٠ فائزين يوميًا،\n٢٠ كرتونة لكل فائز.","zamzamDescription":"١٠ كراتين للفائز، و١٠ يهديها لعشرة أشخاص يختارهم، بحسب الإعلان.","totals":"الإجمالي المعلن للحملة: ١٠٠ رحلة عمرة و١٠٬٠٠٠ كرتون زمزم. لا نستنتج تاريخ النهاية من هذه الأعداد.","startDisplay":"١ نوفمبر ٢٠٢٦","dateNote":"الإعلان الرسمي يذكر الانطلاق يوم الأحد. لم يحدد الإعلان الذي راجعناه تاريخ نهاية المسابقة؛ مدة إتاحة هذه الأداة مستقلة عن مدة الحملة."},"update":{"visible":true,"status":"unverified","title":"هل الحد اليومي أصبح ٣٠٠ فرصة؟","body":"تتداول منشورات فيسبوك رفع الحد إلى ٣٠٠ فرصة يوميًا، وتنسب المعلومة إلى إدارة العناية بالمستفيدين بوزارة الحج والعمرة. لم يتوفر لدينا رابط الرد الرسمي الأصلي للتحقق من صحة النسبة أو تفاصيلها.","caution":"لا نؤكد أن «٣٠٠ فرصة» تعني «٣٠٠ سؤال»، ولا أن كل إجابة تؤهل تلقائيًا للسحب. راجع الشروط والعدد الظاهر داخل التحدي، أو تواصل مع دعم نسك.","sourceLabel":"منشورات فيسبوك؛ الرد الرسمي الأصلي غير متاح.","sourceUrl":"","verifiedAt":"2026-11-04T14:32:15Z"},"guideSteps":[{"num":"١","title":"حمّل التطبيق الرسمي","body":"اختار متجر جهازك من الروابط الرسمية أدناه. لو التطبيق موجود، تأكد من تحديثه من المتجر.","icon":"download"},{"num":"٢","title":"افتح التحدي واقرأ شروطه","body":"سجّل الدخول في نسك وادخل إلى قسم التحدي أو المسابقة المتاح بحسابك. راجع طريقة كسب الفرص والحدود الموضحة فيه.","icon":"gift"},{"num":"٣","title":"انسخ كودًا من هنا","body":"اختار «نسخ الكود» أو «نسخ وفتح نسك». ارجع للتطبيق والصق الكود في المكان المخصص لإضافة المفتاح أو الكود بحسب واجهته.","icon":"copy"},{"num":"٤","title":"راجع رسالة التطبيق","body":"لو تم قبوله، ارجع وعلّمه «تم استخدامه». لو اترفض، اختار «لم يعمل معي»، أو تخطّاه وكمّل. القبول يحدده نسك.","icon":"check"}],"guideMedia":{},"guideVideo":null,"faq":[["هل الموقع تابع لنسك؟","لا. هذه مبادرة شخصية مجانية من أحمد عيد لتسهيل نسخ الأكواد ومتابعتها. المشاركة والسحب والجوائز تتم داخل تطبيق نسك وبحسب شروطه."],["هل نسخ كود يعني أنه اتقبل في التطبيق؟","النسخ ينقل النص فقط. راجع رسالة نسك بعد إدخاله. «تم استخدامه» تأكيد منك لمتابعتك الشخصية، والموقع لا يقرأ نتيجة التطبيق."],["هل عدد الأكواد المنسوخة يساوي فرص السحب؟","لا. العدادات هنا لمتابعة استخدامك للموقع فقط. عدد الفرص وشروط اكتسابها والحد اليومي يوضحها نسك داخل التحدي."],["هل الحد اليومي أصبح ٣٠٠ سؤال أو فرصة؟","تتداول منشورات فيسبوك رقم ٣٠٠ فرصة وتنسبه إلى إدارة العناية بالمستفيدين. لم يتوفر الرد الرسمي الأصلي للتحقق، ولا نؤكد أن هذا يعني ٣٠٠ سؤال. راجع بطاقة التحديث المتداول وشروط التحدي داخل نسك."],["هل هلاقي تقدمي لو رجعت؟","نحفظ تقدمك على نفس المتصفح والجهاز. مسح بيانات المتصفح أو استخدام جهاز مختلف لا ينقل تقدمك؛ صدّر نسخة احتياطية من تاب الأكواد لاستيرادها لاحقًا."],["هل كل الأكواد صالحة؟","القائمة مستوردة من الملف الأصلي الذي جمع أكوادًا من تعليقات عامة. مطابقة الصيغة لا تؤكد قبول الكود أو استمرار صلاحيته. الإضافات الجديدة تظهر مباشرة أو بعد المراجعة وفق إعداد النشر الذي يحدده المدير."]]}'::jsonb) on conflict(id) do nothing;
create or replace function public.touch_site_settings() returns trigger language plpgsql set search_path=public,pg_temp as $$
begin
 if new.content is distinct from old.content or new.auto_approve is distinct from old.auto_approve or new.submissions_enabled is distinct from old.submissions_enabled then
  new.revision=old.revision+1;new.updated_at=now();
 end if;
 return new;
end;$$;
drop trigger if exists site_settings_touch on public.site_settings;
create trigger site_settings_touch before update on public.site_settings for each row execute function public.touch_site_settings();
create or replace function public.bump_codes_revision() returns trigger language plpgsql security definer set search_path=public,pg_temp as $$
begin update public.site_settings set codes_revision=codes_revision+1 where id=1;return null;end;$$;
drop trigger if exists codes_revision_changed on public.codes;
create trigger codes_revision_changed after insert or update or delete on public.codes for each statement execute function public.bump_codes_revision();
-- Preserve the original order and old publication date. Never resurrect a rejected/deleted row on a rerun.
on conflict(code) do nothing;
select setval('public.codes_sort_order_seq',greatest(coalesce((select max(sort_order)from public.codes),0),1),true);
-- Lock one settings row so an auto-approval toggle and a new submission have a defined order.
create or replace function public.submit_public_code(p_code text) returns jsonb
language plpgsql security definer set search_path=public,pg_temp as $$
declare settings public.site_settings%rowtype;new_status text;inserted_id uuid;
begin
 if p_code !~ '^NG-[A-Za-z0-9]{8}$' then raise exception 'Invalid code';end if;
 select * into settings from public.site_settings where id=1 for update;
 if not found then raise exception 'Settings missing';end if;
 if not settings.submissions_enabled then return jsonb_build_object('result','disabled');end if;
 new_status=case when settings.auto_approve then 'approved' else 'pending' end;
 on conflict(code) do nothing returning id into inserted_id;
 if inserted_id is null then return jsonb_build_object('result','duplicate');end if;
 return jsonb_build_object('result','created','status',new_status);
end;$$;
-- Soft-delete a code and resolve its reports in the same transaction; restore is explicit.
create or replace function public.moderate_code(p_id uuid,p_action text,p_code text default null) returns boolean
language plpgsql security definer set search_path=public,pg_temp as $$
declare original_code text;
begin
 select code into original_code from public.codes where id=p_id for update;
 if not found then return false;end if;
 if p_action='delete' then
  update public.codes set status='deleted',deleted_at=now(),reviewed_at=now() where id=p_id;
  update public.reports set resolved=true where code=original_code;
 elsif p_action='restore' or p_action='approve' then
  update public.codes set status='approved',deleted_at=null,reviewed_at=now() where id=p_id;
 elsif p_action='reject' then
  update public.codes set status='rejected',deleted_at=null,reviewed_at=now() where id=p_id;
 elsif p_action='edit' then
  if p_code is null or p_code !~ '^NG-[A-Za-z0-9]{8}$' then raise exception 'Invalid code';end if;
  update public.codes set code=p_code where id=p_id;
 else raise exception 'Invalid moderation action';end if;
 return true;
end;$$;
revoke all on function public.submit_public_code(text) from public,anon,authenticated;
revoke all on function public.moderate_code(uuid,text,text) from public,anon,authenticated;
revoke all on function public.bump_codes_revision() from public,anon,authenticated;
revoke all on function public.touch_site_settings() from public,anon,authenticated;
grant execute on function public.submit_public_code(text) to service_role;
grant execute on function public.moderate_code(uuid,text,text) to service_role;
commit;
